//@ProcessingGroup("condition")
@Component("condition-projector")
public class ConditionProjector extends ConditionEntityProjector {
		
	// core constructor
	public ConditionProjector(ProjectorRegistry registry,
									ConditionRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateConditionEvent
     */
    @EventHandler( payloadType=CreateConditionEvent.class )
    public void handle( CreateConditionEvent event) {
	    LOGGER.info("handling CreateConditionEvent - " + event );
	    Condition entity = new Condition();
            entity.setConditionId( event.getConditionId() );
            entity.setCode( event.getCode() );
            entity.setOnsetDate( event.getOnsetDate() );
            entity.setAbatementDate( event.getAbatementDate() );
            entity.setClinicalStatus( event.getClinicalStatus() );
            entity.setVerificationStatus( event.getVerificationStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCondition( entity );
    }

    /*
     * @param	event UpdateConditionEvent
     */
    @EventHandler( payloadType=UpdateConditionEvent.class )
    public void handle( UpdateConditionEvent event) {
    	LOGGER.info("handling UpdateConditionEvent - " + event );
    	
	    Condition entity = new Condition();
            entity.setConditionId( event.getConditionId() );
            entity.setCode( event.getCode() );
            entity.setOnsetDate( event.getOnsetDate() );
            entity.setAbatementDate( event.getAbatementDate() );
            entity.setPatient( event.getPatient() );
            entity.setClinicalStatus( event.getClinicalStatus() );
            entity.setVerificationStatus( event.getVerificationStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCondition( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCondition( entity );        
    }
    
    /*
     * @param	event DeleteConditionEvent
     */
    @EventHandler( payloadType=DeleteConditionEvent.class )
    public void handle( DeleteConditionEvent event) {
    	LOGGER.info("handling DeleteConditionEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Condition entity = delete( event.getConditionId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCondition( entity );

    }    

    /*
     * @param	event AssignPatientToConditionEvent
     */
    @EventHandler( payloadType=AssignPatientToConditionEvent.class)
    public void handle( AssignPatientToConditionEvent event) {
	    LOGGER.info("handling AssignPatientToConditionEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    Condition entity = assignPatient( event.getConditionId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindCondition( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCondition( entity );
    }
    

	/*
	 * @param	event UnAssignPatientFromConditionEvent
	 */
	@EventHandler( payloadType=UnAssignPatientFromConditionEvent.class)
	public void handle( UnAssignPatientFromConditionEvent event) {
	    LOGGER.info("handling UnAssignPatientFromConditionEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    Condition entity = unAssignPatient( event.getConditionId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindCondition( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllCondition( entity );
	}




    /**
     * Method to retrieve the Condition via an ConditionPrimaryKey.
     * @param 	id Long
     * @return 	Condition
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Condition handle( FindConditionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getConditionId() );
    }
    
    /**
     * Method to retrieve a collection of all Conditions
     *
     * @param	query	FindAllConditionQuery 
     * @return 	List<Condition> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Condition> handle( FindAllConditionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCondition,
 * but only if the id matches
 *
 * @param		entity	Condition
 */
	protected void emitFindCondition( Condition entity ) {
		LOGGER.info("handling emitFindCondition" );
		
	    queryUpdateEmitter.emit(FindConditionQuery.class,
	                            query -> query.getFilter().getConditionId().equals(entity.getConditionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCondition
	 * 
	 * @param		entity	Condition
	 */
	protected void emitFindAllCondition( Condition entity ) {
		LOGGER.info("handling emitFindAllCondition" );
		
	    queryUpdateEmitter.emit(FindAllConditionQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(ConditionProjector.class.getName());

}
